def installed_assistant_origins():
    origins = {name: str(pathlib.Path(sys.modules[name].__file__).resolve()) for name in (*assistant_modules, *publication_modules, *recording_modules, *clip_modules, *reader_modules, *integrity_modules, *incremental_modules, *operations_modules, *ebook_modules, *completion_modules)}
    assert all(pathlib.Path(path).is_relative_to(root / '.venv') for path in origins.values()), origins
    from hashlib import sha256
    for name in (*operations_modules, *completion_modules):
        source = (pathlib.Path.cwd() / 'bootstrap' / '__init__.py' if name == 'bootstrap'
                  else pathlib.Path.cwd() / 'src' / pathlib.Path(*name.split('.')).with_suffix('.py'))
        assert sha256(pathlib.Path(origins[name]).read_bytes()).digest() == sha256(source.read_bytes()).digest(), name
    return origins
print(json.dumps({'assistant_installed_origins': installed_assistant_origins()}), flush=True)
