for suite, contract in reviewed_feature_cases.items():
    module = suite[:-3].replace('/', '.')
    selected = [case for case in publication_cases if case.get('classname', '') == module or case.get('classname', '').startswith(module + '.')]
    assert len(selected) == contract['count'], (suite, len(selected), contract['count'])
    assert len({case.get('name') for case in selected}) == len(selected), (suite, 'duplicate JUnit cases')
    assert all(not any(case.find(tag) is not None for tag in ('failure', 'error', 'skipped')) for case in selected), suite
    observed = {case.get('name', '').split('[', 1)[0] for case in selected}
    assert set(contract['functions']) <= observed, (suite, sorted(set(contract['functions']) - observed))
